import{_ as p,W as o,s as d,u as l,I as t,ah as u,w as s,Z as n,A as a}from"./chunks/framework.DPWZnL3N.js";import"./chunks/theme.DZmP8ALZ.js";const k=JSON.parse('{"title":"如何在 Linux 中使用 find | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 中使用 find | LCTT (201805) | X-CMD","frontmatter":{"pageClass":"x-blog","head":[["meta",{"name":"og:title","content":"如何在 Linux 中使用 find | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 中使用 find | LCTT (201805) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201805/20180427 How to use FIND in Linux","title":"如何在 Linux 中使用 find","tag":"201805"},"relativePath":"201805/20180427 How to use FIND in Linux.md","filePath":"[post].md"}'),c={name:"201805/20180427 How to use FIND in Linux.md"};function g(r,e,m,b,f,h){const i=o("Link");return l(),d("div",null,[e[20]||(e[20]=t("h1",{id:"如何在-linux-中使用-find",tabindex:"-1"},[s("如何在 Linux 中使用 find "),t("a",{class:"header-anchor",href:"#如何在-linux-中使用-find","aria-label":"Permalink to 如何在 Linux 中使用 find"},"​")],-1)),e[21]||(e[21]=t("blockquote",null,[t("p",null,[s("使用正确的参数，"),t("code",null,"find"),s(" 命令是在你的系统上找到数据的强大而灵活的方式。")])],-1)),e[22]||(e[22]=t("p",null,[t("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/rh_003499_01_linux31x_cc.png?itok=Pvim4U-B",alt:""})],-1)),t("p",null,[e[1]||(e[1]=s("在")),n(i,{href:"https://linux.cn/article-9585-1.html"},{default:a(()=>e[0]||(e[0]=[s("最近的一篇文章")])),_:1}),e[2]||(e[2]=s("中，Lewis Cowles 介绍了 ")),e[3]||(e[3]=t("code",null,"find",-1)),e[4]||(e[4]=s(" 命令。"))]),e[23]||(e[23]=u('<p><code>find</code> 是日常工具箱中功能更强大、更灵活的命令行工具之一，因此值得花费更多的时间。</p><p>最简单的，<code>find</code> 跟上路径寻找一些东西。例如：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>find /</span></span></code></pre></div><p>它将找到（并打印出）系统中的每个文件。而且由于一切都是文件，你会得到很多需要整理的输出。这可能不能帮助你找到你要找的东西。你可以改变路径参数来缩小范围，但它不会比使用 <code>ls</code> 命令更有帮助。所以你需要考虑你想要找的东西。</p><p>也许你想在主目录中找到所有的 JPEG 文件。 <code>-name</code> 参数允许你将结果限制为与给定模式匹配的文件。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>find ~ -name &#39;*jpg&#39;</span></span></code></pre></div><p>可是等等！如果它们中的一些是大写的扩展名会怎么样？<code>-iname</code> 就像 <code>-name</code>，但是不区分大小写。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>find ~ -iname &#39;*jpg&#39;</span></span></code></pre></div><p>很好！但是 8.3 名称方案是如此的老。一些图片可能是 .jpeg 扩展名。幸运的是，我们可以将模式用“或”（表示为 <code>-o</code>）来组合。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>find ~ ( -iname &#39;jpeg&#39; -o -iname &#39;jpg&#39; )</span></span></code></pre></div><p>我们正在接近目标。但是如果你有一些以 jpg 结尾的目录呢？ （为什么你要命名一个 <code>bucketofjpg</code> 而不是 <code>pictures</code> 的目录就超出了本文的范围。）我们使用 <code>-type</code> 参数修改我们的命令来查找文件。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>find ~ \\( -iname &#39;*jpeg&#39; -o -iname &#39;*jpg&#39; \\) -type f</span></span></code></pre></div><p>或者，也许你想找到那些命名奇怪的目录，以便稍后重命名它们：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>find ~ \\( -iname &#39;*jpeg&#39; -o -iname &#39;*jpg&#39; \\) -type d</span></span></code></pre></div><p>你最近拍了很多照片，所以让我们把它缩小到上周更改的文件。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>find ~ \\( -iname &#39;*jpeg&#39; -o -iname &#39;*jpg&#39; \\) -type f -mtime -7</span></span></code></pre></div><p>你可以根据文件状态更改时间 （<code>ctime</code>）、修改时间 （<code>mtime</code>） 或访问时间 （<code>atime</code>） 来执行时间过滤。 这些是在几天内，所以如果你想要更细粒度的控制，你可以表示为在几分钟内（分别是 <code>cmin</code>、<code>mmin</code> 和 <code>amin</code>）。 除非你确切地知道你想要的时间，否则你可能会在 <code>+</code> （大于）或 <code>-</code> （小于）的后面加上数字。</p><p>但也许你不关心你的照片。也许你的磁盘空间不够用，所以你想在 <code>log</code> 目录下找到所有巨大的（让我们定义为“大于 1GB”）文件：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>find /var/log -size +1G</span></span></code></pre></div><p>或者，也许你想在 <code>/data</code> 中找到 bcotton 拥有的所有文件：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>find /data -owner bcotton</span></span></code></pre></div><p>你还可以根据权限查找文件。也许你想在你的主目录中找到对所有人可读的文件，以确保你不会过度分享。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>find ~ -perm -o=r</span></span></code></pre></div><p>这篇文章只说了 <code>find</code> 能做什么的表面。将测试条件与布尔逻辑相结合可以为你提供难以置信的灵活性，以便准确找到要查找的文件。并且像 <code>-exec</code> 或 <code>-delete</code> 这样的参数，你可以让 <code>find</code> 对它发现的内容采取行动。你有任何最喜欢的 <code>find</code> 表达式么？在评论中分享它们！</p><hr>',25)),t("p",null,[e[6]||(e[6]=s("via: ")),n(i,{href:"https://opensource.com/article/18/4/how-use-find-linux"},{default:a(()=>e[5]||(e[5]=[s("https://opensource.com/article/18/4/how-use-find-linux")])),_:1})]),t("p",null,[e[11]||(e[11]=s("作者：")),n(i,{href:"https://opensource.com/users/bcotton"},{default:a(()=>e[7]||(e[7]=[s("Ben Cotton")])),_:1}),e[12]||(e[12]=s(" 选题：")),n(i,{href:"https://github.com/lujun9972"},{default:a(()=>e[8]||(e[8]=[s("lujun9972")])),_:1}),e[13]||(e[13]=s(" 译者：")),n(i,{href:"https://github.com/geekpi"},{default:a(()=>e[9]||(e[9]=[s("geekpi")])),_:1}),e[14]||(e[14]=s(" 校对：")),n(i,{href:"https://github.com/wxy"},{default:a(()=>e[10]||(e[10]=[s("wxy")])),_:1})]),t("p",null,[e[17]||(e[17]=s("本文由 ")),n(i,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>e[15]||(e[15]=[s("LCTT")])),_:1}),e[18]||(e[18]=s(" 原创编译，")),n(i,{href:"https://linux.cn/"},{default:a(()=>e[16]||(e[16]=[s("Linux中国")])),_:1}),e[19]||(e[19]=s(" 荣誉推出"))])])}const C=p(c,[["render",g]]);export{k as __pageData,C as default};
